// === Tab: mySketch.js ===
let mRenderer, mScene, mCamera, mScreenQuad;
let mTexture1, mTexture2, mTexture3;
let feedbackMaterial, paintMaterial, screenMaterial, debugScreenMaterial;

let mStep = 0;
let uiTwo = 3; 
let timesteps = 4; 
let mMinusOnes;

let params = {
    curlf: 0.256,
    fluxf: 0.128,
    divf: 0.01,
    lapf: 0.04,
    feedf: 1.001,
    expf: 0.2,
    mixf: 0.85,
    offf: 0.0,
    sofff: 1.0,
    scalef: 5.0,
    flockf: 0.5,
    frustf: 0.4,
    contf: 0.0,
    brushsize: 30.0,
    paintcolor: "#980000"
};

let mUniforms;
let textureWidth = 1024;
let textureHeight = 512;

function setup() {
    let p5Canvas = createCanvas(windowWidth, windowHeight, WEBGL);
    let canvasElement = p5Canvas.elt; 

    let gl = canvasElement.getContext('webgl2') || canvasElement.getContext('webgl');
    mMinusOnes = new THREE.Vector2(-1, -1);

    mUniforms = {
        screenWidth:  { value: textureWidth },
        screenHeight: { value: textureHeight },
        tSource:      { value: null },
        sSource:      { value: null },
        iSource:      { value: null },
        loadImage:    { value: 0.0 }, 
        mixf:         { value: params.mixf },
        curlf:        { value: params.curlf },
        fluxf:        { value: params.fluxf },
        divf:         { value: params.divf },
        lapf:         { value: params.lapf },
        feedf:        { value: params.feedf },
        expf:         { value: params.expf },
        offf:         { value: params.offf },
        flockf:       { value: params.flockf },
        frustf:       { value: params.frustf },
        sofff:        { value: params.sofff },
        scalef:       { value: params.scalef },
        contf:        { value: params.contf },
        brushsize:    { value: params.brushsize },
        brush:        { value: mMinusOnes },
        color:        { value: new THREE.Vector4(0.588, 0, 0, 0) }
    };

    try {
        mRenderer = new THREE.WebGLRenderer({
            canvas: canvasElement,
            context: gl,
            preserveDrawingBuffer: true
        });
        mRenderer.setSize(windowWidth, windowHeight);
		  mRenderer.setClearColor(0xffffff, 1.0);
    } catch (e) {
        console.error("Three.js false:", e);
        return;
    }

    mScene = new THREE.Scene();
    mCamera = new THREE.OrthographicCamera(-0.5, 0.5, 0.5, -0.5, -1, 1);
    mCamera.position.z = 0;
    mScene.add(mCamera);

    feedbackMaterial = getShaderMaterial('smokeFluidFragmentShader');
    paintMaterial = getShaderMaterial('paintFragmentShader');
    screenMaterial = getShaderMaterial('screenFragmentShader');
    debugScreenMaterial = getShaderMaterial('debugScreenFragmentShader');

    let plane = new THREE.PlaneGeometry(1.0, 1.0);
    mScreenQuad = new THREE.Mesh(plane, screenMaterial);
    mScene.add(mScreenQuad);

    mTexture1 = getWrappedRenderTarget();
    mTexture2 = getWrappedRenderTarget();
    mTexture3 = getWrappedRenderTarget();
}

function draw() {
    updateUniformsData();

    for (let i = 0; i < timesteps; ++i) {
        let pStep = mStep % uiTwo;

        if (pStep == 0) {
            renderToTarget(feedbackMaterial, mTexture1, mTexture3, mTexture2);
            renderToTarget(paintMaterial, mTexture2, mTexture3, mTexture1);
        } else if (pStep == 1) {
            renderToTarget(feedbackMaterial, mTexture2, mTexture1, mTexture3);
            renderToTarget(paintMaterial, mTexture3, mTexture1, mTexture2);
        } else if (pStep == 2) {
            renderToTarget(feedbackMaterial, mTexture3, mTexture2, mTexture1);
            renderToTarget(paintMaterial, mTexture1, mTexture2, mTexture3);
        }

        mUniforms.brush.value = mMinusOnes;
        mStep++;
    }

    mScreenQuad.material = screenMaterial;
    mRenderer.render(mScene, mCamera);
}

function getWrappedRenderTarget() {
    return new THREE.WebGLRenderTarget(textureWidth, textureHeight, {
        minFilter: THREE.LinearFilter,
        magFilter: THREE.LinearFilter,
        format:    THREE.RGBAFormat, 
        type:      THREE.FloatType,  
        wrapS:     THREE.RepeatWrapping,
        wrapT:     THREE.RepeatWrapping
    });
}

function getShaderMaterial(fragmentShaderId) {
    let vertElem = document.getElementById('standardVertexShader');
    let fragElem = document.getElementById(fragmentShaderId);

    if (!vertElem || !fragElem) {
        console.error("can not find GLSL id: " + fragmentShaderId);
        return new THREE.MeshBasicMaterial({ color: 0xff0000 });
    }

    return new THREE.ShaderMaterial({
        uniforms: mUniforms,
        vertexShader: vertElem.textContent,
        fragmentShader: fragElem.textContent
    });
}

function renderToTarget(material, tSource, sSource, target) {
    mScreenQuad.material = material;
    mUniforms.tSource.value = tSource.texture; 
    mUniforms.sSource.value = sSource.texture;
    mRenderer.setRenderTarget(target);
    mRenderer.render(mScene, mCamera);
    mRenderer.setRenderTarget(null); 
}

function updateUniformsData() {
    mUniforms.curlf.value  = params.curlf;
    mUniforms.fluxf.value  = params.fluxf;
    mUniforms.divf.value   = params.divf;
    mUniforms.lapf.value   = params.lapf;
    mUniforms.feedf.value  = params.feedf;
    mUniforms.expf.value   = params.expf;
    mUniforms.flockf.value = params.flockf;
    mUniforms.frustf.value = params.frustf;
    mUniforms.sofff.value  = params.sofff;
    mUniforms.scalef.value = params.scalef;
    mUniforms.contf.value  = 1.0 + 0.005 * params.contf;
    mUniforms.mixf.value   = Math.exp(10 * (params.mixf - 1.0));
    mUniforms.offf.value   = 0.0;
    mUniforms.brushsize.value = params.brushsize;

    let rgb = parseColorToRGB(params.paintcolor);
    mUniforms.color.value.set(rgb[0] / 255.0, rgb[1] / 255.0, rgb[2] / 255.0, 0.0);
}

function mouseDragged() {
    let mx = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) / width;
    let my = 1.0 - ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) / height);
    mUniforms.brush.value.set(mx, my);
}

function mousePressed() {
    var mx = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) / width;
    var my = 1.0 - ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) / height);
    mUniforms.brush.value.set(mx, my);
}

function parseColorToRGB(hex) {
    let m = hex.match(/^#([0-9a-f]{6})$/i);
    if (m) {
        return [
            parseInt(m[1].substr(0, 2), 16),
            parseInt(m[1].substr(2, 2), 16),
            parseInt(m[1].substr(4, 2), 16)
        ];
    }
    return [152, 0, 0];
}

function windowResized() {
    resizeCanvas(windowWidth, windowHeight);
    if (mRenderer) mRenderer.setSize(windowWidth, windowHeight);
}

